mapper.insert:
INSERT INTO attendance_evidence_subject_lock (
    company_id, employee_id, touched_at
) VALUES (
    #{companyId}, #{employeeId}, #{touchedAt}
)
ON DUPLICATE KEY UPDATE touched_at = VALUES(touched_at)

mapper.select:
SELECT employee_id
FROM attendance_evidence_subject_lock
WHERE company_id = #{companyId}
  AND employee_id = #{employeeId}
FOR UPDATE

SELECT raw_attendance_fact_id, attendance_source_id, company_id,
       fact_kind, source_business_key, source_version,
       stable_fingerprint, source_time_text, source_time_zone,
       source_instant, interval_start, interval_end,
       canonical_payload_digest, raw_object_ref, request_id,
       received_at, created_by
FROM raw_attendance_fact
WHERE attendance_source_id = #{sourceId}
  AND source_business_key = #{sourceBusinessKey}
  AND source_version = #{sourceVersion}

mapper.insert:
INSERT INTO employee_match_decision (
    employee_match_decision_id, normalized_attendance_record_id,
    match_status, match_reason, employee_id, employment_period_id,
    device_person_binding_id, resolver_snapshot_digest, created_at
) VALUES (
    #{employeeMatchDecisionId}, #{normalizedAttendanceRecordId},
    #{matchStatus}, #{matchReason}, #{employeeId},
    #{employmentPeriodId}, #{devicePersonBindingId},
    #{resolverSnapshotDigest}, #{createdAt}
)

mapper.select:
SELECT event.effective_attendance_event_id,
       event.company_id, event.employee_id, event.event_kind,
       event.normalized_direction, event.point_instant,
       event.interval_start, event.interval_end,
       event.canonical_digest, event.created_at
FROM effective_attendance_event event
WHERE event.company_id = #{companyId}
  AND event.employee_id = #{employeeId}
  AND event.point_instant BETWEEN #{windowStart} AND #{windowEnd}
  AND event.normalized_direction = #{normalizedDirection}
ORDER BY event.point_instant, event.effective_attendance_event_id

mapper.insert:
INSERT INTO effective_attendance_event (
    effective_attendance_event_id, company_id, employee_id,
    event_kind, normalized_direction, point_instant,
    interval_start, interval_end, canonical_digest, created_at
) VALUES (
    #{effectiveAttendanceEventId}, #{companyId}, #{employeeId},
    #{eventKind}, #{normalizedDirection}, #{pointInstant},
    #{intervalStart}, #{intervalEnd}, #{canonicalDigest}, #{createdAt}
)

INSERT INTO effective_event_lifecycle_fact (
    effective_event_lifecycle_fact_id, effective_attendance_event_id,
    lifecycle_type, related_event_id, source_reversal_record_id,
    knowledge_at, actor_id, request_id, change_reason, fact_digest
) VALUES (
    #{effectiveEventLifecycleFactId}, #{effectiveAttendanceEventId},
    #{lifecycleType}, #{relatedEventId}, #{sourceReversalRecordId},
    #{knowledgeAt}, #{actorId}, #{requestId}, #{changeReason},
    #{factDigest}
)

INSERT INTO evidence_link (
    evidence_link_id, effective_attendance_event_id,
    raw_attendance_fact_id, normalized_attendance_record_id,
    employee_match_decision_id, link_type, created_at
) VALUES (
    #{evidenceLinkId}, #{effectiveAttendanceEventId},
    #{rawAttendanceFactId}, #{normalizedAttendanceRecordId},
    #{employeeMatchDecisionId}, #{linkType}, #{createdAt}
)

mapper.select:
SELECT COUNT(*)
FROM evidence_link
WHERE effective_attendance_event_id = #{effectiveAttendanceEventId}
  AND raw_attendance_fact_id = #{rawAttendanceFactId}

SELECT document.oa_attendance_document_id
FROM oa_attendance_document document
WHERE document.attendance_source_id = #{sourceId}
  AND document.source_business_key = #{sourceBusinessKey}
  AND document.source_version = #{sourceVersion}
LIMIT 1

SELECT COUNT(*)
FROM oa_attendance_document_context context
WHERE context.oa_attendance_document_id = #{oaAttendanceDocumentId}
